ht:1.8;color:#8595b0;margin:26px 0 0}.board-credit a{color:#a9bad5;margin-left:8px}@media(max-width:1100px){.group-grid,.group-grid.daily{grid-template-columns:1fr}.group-grid.compact{grid-template-columns:1fr}}@media(max-width:650px){.claude-workboard{padding:20px 14px;border-radius:16px}.board-title h2{font-size:19px}.board-title .board-role{display:none}.board-summary{flex-direction:column}.state-chips{gap:5px}.state-chips button{padding:8px;font-size:10px}}
</style>
